// ModelXD Playground (owner, Sep 14): an image-led create/remix gallery.
// Four finished artworks and two text scenario presets. Every item carries an
// image prompt and a separate, concise motion prompt; the page prefills
// XDuel (image duel) and XDirect (film) with them and never runs anything.
//
// Provenance: the vampire artwork is an original character generated by
// Codex with its built-in image generation (playground-assets/manifest.json,
// 2026-09-14, "Not a ModelXD generation or duel result"). The three game
// works are unofficial fan concepts from the same tool
// (game-gallery-assets/manifest.json). No item is an XDuel result; no model
// name, price or vote is attached. Artwork image prompts are the manifest
// strings verbatim; motion prompts and the presets were written for this
// page. image = the supplied 1672x941 PNG (lightbox); thumb = a JPEG copy of
// the same file for cards and the home hero.
export type Bilingual = { en: string; ja: string }
export type PgArtwork = {
  kind: 'artwork'
  original: boolean          // false = unofficial fan art of a named game
  slug: string
  image: string
  thumb: string
  title: Bilingual
  reference: Bilingual
  alt: Bilingual
  imagePrompt: string        // manifest prompt, verbatim (English)
  videoPrompt: Bilingual
}
export type PgPreset = {
  kind: 'preset'
  slug: string
  emoji: string
  title: Bilingual
  blurb: Bilingual
  imagePrompt: Bilingual
  videoPrompt: Bilingual
}
export type PgItem = PgArtwork | PgPreset

