export const PG_ARTWORKS = PG_ITEMS.filter((i): i is PgArtwork => i.kind === 'artwork')
export const PG_PRESETS  = PG_ITEMS.filter((i): i is PgPreset => i.kind === 'preset')
/** The Japanese home's hero picture: the vampire (owner, Sep 14). */
export const PG_HERO = PG_ARTWORKS[0]

export const pick = (v: Bilingual, lang: string): string => (lang === 'ja' ? v.ja : v.en)
export const imagePromptOf = (i: PgItem, lang: string): string => (i.kind === 'artwork' ? i.imagePrompt : pick(i.imagePrompt, lang))
